package ama.api;
import ama.storage.*;import ama.config.*;import ama.config.file.*;import ama.transcript.*;import ama.contract.ConfigArchiveContracts.*;import java.net.URI;import java.nio.file.*;import java.sql.Connection;import java.sql.SQLException;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import javax.net.ssl.SSLContext;import org.springframework.jdbc.datasource.AbstractDataSource;import org.springframework.boot.test.context.runner.ApplicationContextRunner;import org.springframework.context.support.GenericApplicationContext;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Real production configuration wiring, no servlet/DB/network; transport mock cannot grant authority. */
class Task11B3LifecycleAssemblyTest {
 static final class NoSql extends AbstractDataSource {final AtomicInteger calls=new AtomicInteger();public Connection getConnection()throws SQLException{calls.incrementAndGet();throw new SQLException("No offline SQL capability");}public Connection getConnection(String u,String p)throws SQLException{return getConnection();}}
 Task11B3LifecycleApi.Settings settings(Path archive,boolean unavailable)throws Exception {
  var raw=new ArrayList<RawArchive>();for(String name:List.of("codec","confirmation","parser","processing1")){ArtifactType type=switch(name){case "codec"->ArtifactType.CANONICAL_CODEC;case "confirmation"->ArtifactType.CONFIRMATION_HASH;case "parser"->ArtifactType.PARSER_CONFIG;default->ArtifactType.PROCESSING_CONFIG;};String version=switch(name){case "codec"->"ama.canonical-value.v1";case "confirmation"->"ama.transcript-confirmation.v1";case "parser"->"ama.strict-utf8-lines.v1";default->"b06.controlled.import-txt.1";};try(var in=getClass().getResourceAsStream("/ama/transcript/restart/"+name+".json")){assertNotNull(in);raw.add(new RawArchive(type,version,in.readAllBytes()));}}
  var budget=Task11B2ReceiptApi.archiveBudget();var index=new ConfigArchiveIndex.IndexBudget(4194304,4096,67108864,128);String pin=new ControlledArchiveReleaseWriter().publish(archive,null,raw,index,budget,()->false);var snapshot=new ControlledConfigArchiveSource().open(archive,pin,index,budget,()->false);Ref processing=snapshot.index().entries().stream().map(ConfigArchiveIndex.Entry::ref).filter(r->r.artifactType()==ArtifactType.PROCESSING_CONFIG).findFirst().orElseThrow();return new Task11B3LifecycleApi.Settings(archive,pin,processing,new Ref(ArtifactType.PROMPT_CONFIG,"unit-v1","0".repeat(64)),new Ref(ArtifactType.MODEL_CONFIG,"unit-v1","0".repeat(64)),archive.resolve("no-private-identities.json"),URI.create("http://127.0.0.1:1"),unavailable);
 }
 void wiring(boolean unavailable,boolean clientPresent)throws Exception {Path workspace=Path.of(System.getenv("AMA_TASK11_REPOSITORY_ROOT"),".superpowers");Path archive=Files.createTempDirectory(workspace,"b3-lifecycle-unit-archive-");Files.setPosixFilePermissions(archive,java.nio.file.attribute.PosixFilePermissions.fromString("rwx------"));var source=new NoSql();var storage=new LocalFileClient(URI.create("https://localhost:1"),SSLContext.getDefault());var binding=new ManagedBackendId.Local("https://localhost:1","00000000-0000-4000-8000-000000008001","unit","overlay");var definitions=new FileBackendDefinitions(List.of(new FileBackendCatalog.Backend(binding.id(),"local",1,"WRITABLE",storage,binding)),binding.id());try{var configured=Task11B3LifecycleApi.properties(settings(archive,unavailable));String[] properties=configured.entrySet().stream().map(e->e.getKey()+"="+e.getValue()).toArray(String[]::new);var runner=new ApplicationContextRunner().withUserConfiguration(Task11B3LifecycleApi.Wiring.class).withInitializer(context->Task11B3LifecycleApi.infrastructure((GenericApplicationContext)context,source,definitions)).withPropertyValues(properties);if(clientPresent)runner=runner.withBean(ControlledKnowledgeClient.class,()->mock(ControlledKnowledgeClient.class));runner.run(context->{if(context.getStartupFailure()!=null)throw new AssertionError("Actual source assembly failure",context.getStartupFailure());var runtime=context.getBean(MinutesConfiguration.Runtime.class);assertNotNull(runtime.localPublications());assertNotNull(runtime.editor());assertNotNull(runtime.finals());assertSame(context.getBean(ProcessingConfiguration.Runtime.class).components().registry(),context.getBean(ama.storage.FileRegistry.class));if(clientPresent)assertNotNull(runtime.publications());else assertNull(runtime.publications());assertEquals(0,source.calls.get(),"Wiring must not configure storage or open SQL; only owned public processing archive admission is expected");assertTrue(context.getBeansOfType(ama.worker.WorkerLoop.class).isEmpty());assertTrue(context.getBeansOfType(ama.worker.ReconciliationLoop.class).isEmpty());});}finally{try{Task11B3LifecycleApi.closeOwnedNativeClient(storage);}finally{assertTrue(archive.toRealPath().startsWith(workspace.toRealPath())&&archive.getFileName().toString().startsWith("b3-lifecycle-unit-archive-"));try(var files=Files.walk(archive)){for(Path file:files.sorted(Comparator.reverseOrder()).toList())Files.delete(file);}}}}
 @Test void actualProductionCompositionHasRealArchiveAdmissionWithoutStorageRpcOrSql()throws Exception {wiring(false,true);}
 @Test void missingMinutesArchiveStillAllowsMetadataQueueCompositionForRealPrepareFailure()throws Exception {wiring(true,true);}
 @Test void missingProviderLeavesNewPublicationUnavailableAndLocalRecoveryInstalled()throws Exception {wiring(false,false);}
}